	["安卓微信区"]={Key="安卓微信区", en="Android WeChat", fr="WeChat Android", de="Android WeChat", pt="Android WeChat", es="WeChat para Android", ru="Android WeChat", ja="Android用WeChatサーバー", ko="WeChat (Android)", zh="安卓微信区", zhHK="Android WeChat", zhTW="安卓微信區", th="เซิร์ฟ Android WeChat", vi="WeChat trên Android", id="WeChat untuk Android", tr="Android WeChat"}, 
